        answer_in_gold += 1
    elif ae & gold_set:
        answer_partial += 1

print(f'answer_evidence 完整在 gold 链中: {answer_in_gold}/{len(records)}')
print(f'answer_evidence 部分在 gold: {answer_partial}')
