            neg_set = set(c.get('chain',[]))
            overlap = len(gold_set & neg_set) / max(len(gold_set), 1)
            bucket = 'shared>=50%' if overlap>=0.5 else ('shared>=25%' if overlap>=0.25 else 'shared<25%')
            hard_neg[(c['type'], bucket)] += 1

print('\n=== 负样本与 gold 链重叠分布 ===')
